INSERT INTO books (id, title, author, description, genre, price, cover_image, created_at) VALUES
(7, 'Biology', 'anishtain', 'Biology is a natural science discipline that studies living things. It is a very large and broad field due to the wide variety of life found on Earth, so individual biologists normally focus on specific fields. These fields are either categorized by the scale of life or by the types of organisms studied.', 'Science', '5.50', 'imges/All_section/biology.png', '2024-12-08 19:19:07'),
(8, 'The Danger Bridge', 'Helene Mayfield', 'An ex-service man of the famous British West African Frontier Force comes back to devote himself as a benevolent worker.', 'Mystery', '10.00', 'imges/All_section/bridge.png', '2024-12-08 19:21:56'),
(9, 'Dark', 'Allison Saft', 'initially to investigate claims that the house is haunted. There he discovers that those engulfed by the darkness are driven to savage and murderous frenzies, in connection with a mysterious cult leader whose spirit inhabits the darkness', 'Mystery', '12.00', 'imges/All_section/dark.png', '2024-12-08 19:24:37'),
(10, 'A Minor Fall', 'Price Ainsworth', 'it is a modern interpretation of an Old Testament saga. Davy Jessie is a young, personal injury trial lawyer working as an associate in a top-drawer law firm in Houston, Texas in 2005.', 'Drama', '11.00', 'imges/All_section/fall.png', '2024-12-08 19:33:16'),
(11, 'Ill-Fame', 'Erik Rivenes', 'Looking for a better life, prostitute Nora Simms arrives in Gold Rush San Francisco with a plan for success: to strike it rich by trading on her good looks.', 'Crime', '13.90', 'imges/All_section/ILL.png', '2024-12-08 19:34:45'),
(12, 'Lake Town', 'Marina Boat', 'iPego\'s story collection looks at love, loss, and the search for the meaning of life in a small Illinois town.', 'Historical', '15.00', 'imges/All_section/lake.png', '2024-12-08 19:37:07'),
(13, 'The Mirror of Destiny', 'Sebastian Bennett', 'Altered by a talisman of great power, she escapes her unwanted lot -- joining a commander\'s tragically blinded son on a remarkable journey from peril to peril.', 'Mystery', '23.00', 'imges/All_section/mirror.png', '2024-12-08 19:40:19'),
(14, 'The Murder That Took Place Last Night', 'Joao Cancelo', 'I’ve woken up with the hangover from hell, a stranger in my bed, and I’ve gone viral for the worst reasons.\n\nThere’s only one thing stopping me from dying of shame. I need to find a killer.', 'Crime', '20.89', 'imges/All_section/murder.png', '2024-12-08 19:42:37'),
(15, 'Roman', 'Olivia Wilson', 'is a detailed explanation of the Gospel message written by Paul to the church in Rome. See how Paul lays out the surprising message of Jesus\' new covenant in this carefully crafted letter.', 'Historical', '9.90', 'imges/All_section/roman.png', '2024-12-08 19:44:06'),
(16, 'My Little Secret', 'Claudia Wilson', 'what follows is a twisty, heartbreaking story of grief, loss, and the ties that bind a family together—and the secrets that might tear them up.', 'Horror', '17.60', 'imges/All_section/secret.png', '2024-12-08 19:45:46'),
(17, 'Skeleton Man', 'Joseph Bruchac', 'Molly remembers the Mohawk legend of a man so hungry he ate himself and everyone in his village, except for one brave girl.', 'Mystery', '14.00', 'imges/All_section/skeleton.png', '2024-12-08 19:47:12'),
(18, 'Spear', 'Neil Tran', 'Spear is a 2022 Horror novella by Neil Tran. Drawing on Arthurian mythos, the book refashions the story of Percival and the Holy Grail', 'Horror', '15.00', 'imges/All_section/Spears.png', '2024-12-08 19:49:14'),
(19, 'Sword', 'Olivia Wilson', 'An extraordinary young artist brings the history of this noble weapon — and its skillful masters — into stunningly sharp relief.', 'Historical', '19.00', 'imges/All_section/sword.png', '2024-12-08 19:50:29'),
(20, 'Virtue', 'Olivia Wilson', 'This Very Short Introduction introduces readers to the various virtues: the moral virtues, the intellectual virtues, and the theological virtues.', 'Historical', '21.00', 'imges/All_section/virtue.png', '2024-12-08 19:53:51'),
(21, 'Young Wizard', 'Aaron Loeb', 'The Young Wizards series presently consists of eleven books, focusing on the adventures of two young wizards named Nita and Kit.', 'Fantasy', '27.00', 'imges/All_section/wizard.png', '2024-12-08 19:56:02'),
(22, 'Wonderbloom', 'Estelle Darcy', 'Tyrant Albino X is in power in the Western Cape and rules from his Vergelegen throne. Magriet Vos needs to escape his clutches, as well as her own memory loss.', 'Drama', '18.00', 'imges/All_section/wonderbloom.png', '2024-12-08 19:57:40'),
(23, '1984', 'George Orwell', '1984 is a dystopian novel tells the story of Winston Smith, a citizen of the miserable society of Oceania, who is trying to rebel against the Party and its omnipresent symbol, Big Brother.', 'Crime', '10.00', 'imges/Best_Seller_Section/1984.png', '2024-12-08 20:00:10'),
(24, 'Alone', 'Salem Aldossary', 'he\'s alone―left behind in a town that has been mysteriously evacuated and abandoned.', 'Horror', '11.00', 'imges/Best_Seller_Section/alone.png', '2024-12-08 20:01:41'),
(25, 'Angel of Death', 'Alex Rainer', 'A search for a missing girl leads detective Alex Rainer into a run-down apartment in Whitechapel, London.', 'Mystery', '12.00', 'imges/Best_Seller_Section/angel.png', '2024-12-08 20:08:49'),
(26, 'The Deep Ocean', 'Hannah Morales', 'The Deep Ocean is an epic excursion into one of the last great frontiers on Earth. The Deep Ocean is a beautiful hardback book. It is packed with images and illustrations of the life found in this dark and cold environment.', 'Drama', '14.00', 'imges/Best_Seller_Section/drop.png', '2024-12-08 20:10:51'),
(27, 'The Forest', 'Fahad Almold', 'Set amid the glimmering lakes and disappearing forests of the early United States, The Forest imagines how a wide variety of Americans experienced their lives.', 'Science', '11.99', 'imges/Best_Seller_Section/forest.png', '2024-12-08 20:12:18'),
(28, 'The Light Jar', 'Lisa Thompson', 'The Light Jar is a captivating story of fear and hope, loneliness and friendship, and finding the light within, even in the darkest of times.', 'Fantasy', '11.00', 'imges/Best_Seller_Section/jar.png', '2024-12-08 20:13:38'),
(29, 'NightBooks', 'J.A White', 'A boy is imprisoned by a witch and must tell her a new scary story each night to stay alive. Alex\'s hair-raising tales are the only thing keeping the witch Natacha happy, but soon he\'ll run out of pages to read from and be trapped fore‏ver.', 'Horror', '14.00', 'imges/Best_Seller_Section/notebook.png', '2024-12-08 20:19:30'),
(30, 'Thread', 'Olivia Wilson', 'the story of two young girls: Clara and Yuming. Clara is your average twelve-year old American girl… except for the fact that her sister recently passed away.', 'Drama', '29.99', 'imges/Best_Seller_Section/thread.png', '2024-12-08 20:22:41'),
(31, 'Time', 'Olivia Wilson', 'This story is a refreshing, wonderful read focusing on two queer characters who have been begging for a novel of their own.', 'Historical', '15.00', 'imges/Best_Seller_Section/time.png', '2024-12-08 20:24:45'),
(32, 'Echoes of The Unsolved', 'Margarita Perez', 'This enthralling book invites you on a captivating journey through time, where shadows of the past linger, and whispers.', 'Horror', '19.00', 'imges/Best_Seller_Section/unsolved.png', '2024-12-08 20:26:39'),
(33, 'AetherBound', 'E.K. Johnston', 'During a space-station layover, Pendt escapes and forms a lucky bond with the Brannick twins, the teenage heirs of the powerful family that owns the station. Against all odds, the trio hatches a long-shot scheme to take over the station and thwart the destinies they never wished for.', 'Mystery', '26.00', 'imges/Mystery_Section/aether.png', '2024-12-08 20:29:09'),
(34, 'Cold Lake', 'Jeff Carson', 'Their grim discoveries reopen a cold case Wolf\'s father worked twenty-two years ago, and Wolf must try to succeed where his father failed before him. Wolf has the advantage on his dad, however, because he has bodies. Lots of them.', 'Mystery', '17.00', 'imges/Mystery_Section/cold.png', '2024-12-08 20:30:11'),
(35, 'Eight Will Fall', 'Sarah Harian', 'In a world where magic is illegal, eight criminals led by rebellious Larkin are sent on a mission to rid their realm of an ancient evil lurking beneath the surface.', 'Mystery', '22.00', 'imges/Mystery_Section/fall.png', '2024-12-08 20:31:27'),
(36, 'Into The Gray', 'Margarita Killjoy', 'Into the Grey is a young adult ghost story about two twin brothers, Pat and Dom, who find themselves haunted after their family home is burned down.', 'Science', '24.00', 'imges/Mystery_Section/gray.png', '2024-12-08 20:33:11'),
(37, 'Haven Fall', 'Sarah Holland', 'Havenfall is an escape from reality, where her mother sits on death row accused of murdering Maddie\'s brother. It\'s where Maddie fell in love with handsome Fiorden soldier Brekken.', 'Mystery', '20.00', 'imges/Mystery_Section/haven.png', '2024-12-08 20:34:40'),
(38, 'Long Lost', 'Jacqueline West', 'A mysterious book leads a girl into a century-old supernatural mystery. When Fiona\'s family moves across Massachusetts to Lost Lake, a small town that\'s far closer to her older sister Arden\'s figure skating club, Fiona resents both being uprooted and the constant focus on her accomplished sibling.', 'Mystery', '21.00', 'imges/Mystery_Section/longlost.png', '2024-12-08 20:35:56'),
(39, 'Murder Mystery', 'Hamdallah', 'A murder mystery is a fast-paced story in which a killing is committed, and the characters must solve the mystery by uncovering clues and identifying the culprit.', 'Mystery', '13.00', 'imges/Mystery_Section/mrdms.png', '2024-12-08 20:37:18'),
(40, 'Lost in The Never Woods', 'Aiden Thomas', 'When children start to go missing in the local woods, a teen girl must face her fears and a past she can\'t remember to rescue them in this atmospheric YA novel, Lost in the Never Woods from the author of Cemetery Boys.', 'Mystery', '14.00', 'imges/Mystery_Section/never.png', '2024-12-08 20:38:16'),
(41, 'Brimstone', 'Cherie priest', 'FBI Special Agent Aloysius X.L. Pendergast and Sergeant Vincent D\'Agosta, now working for the Southampton Police Department, investigate a series of unusual deaths—deaths that appear to be the work of Lucifer in return for pacts entered in with him by his victims.', 'Mystery', '30.00', 'imges/Mystery_Section/primstone.png', '2024-12-08 20:39:43'),
(42, 'Those Eves', 'Raymond Beckham', 'The Eves is a multi-generational novel portraying lives lived well and lives in transition. Filled with poignancy and horror.', 'Horror', '22.00', 'imges/Mystery_Section/those.png', '2024-12-08 20:44:07'),
(43, 'Tomo Visurnakcio Parkas', 'Philippa Pearce', 'Tribe tells the hidden history of the Mountains of the Moon, the glacier-crowned lost world of incomparable beauty that lies at the heart of equatorial Africa.', 'Crime', '25.00', 'imges/Mystery_Section/tomo.png', '2024-12-08 20:46:24'),
(44, 'The Walking That Kills', 'Stephen Gregory', 'A dark novel of Possession. The ghosts that haunt us are not always strangers.', 'Crime', '26.66', 'imges/Mystery_Section/walking.png', '2024-12-08 20:47:49'),
(45, 'Where The Woods End', 'Charlotte Salter', 'Kestrel, a young huntress, lives in a seemingly endless forest crawling with dangerous beasts. But the most dangerous beasts of all are the Grabbers--beings that are born when you are and stalk you throughout your life, waiting for the perfect moment to snatch and eat you.', 'Mystery', '27.11', 'imges/Mystery_Section/woods.png', '2024-12-08 20:48:56'),
(46, 'Our Secret Love', 'Claudia Wilson', 'Dana Lipton has totally fallen for Chris Geller. Who wouldn\'t? He\'s sexy, funny, and smart--and he\'s just as crazy about Dana as she is about him. But there\'s one problem: Chris is her older brother Brian\'s best friend, and he\'s supposed to be off-limits.', 'Romantic', '11.99', 'imges/Romantic_Section/1.png', '2024-12-08 20:50:37'),
(47, 'Love Story', 'Lorna Alvarado', 'Love Story (1970), a romance novel by Lorna Alvarado, follows the trials and tribulations of a young couple\'s ill-fated relationship.', 'Romantic', '14.00', 'imges/Romantic_Section/2.png', '2024-12-08 20:51:46'),
(48, 'The Time Love Story', 'Takeehiro Kanegi', 'The series follows Takashi Natsume, an orphan boy in his late teens who can perceive and combat yōkai. One day, Takashi finds a very old notebook.', 'Romantic', '15.99', 'imges/Romantic_Section/3.png', '2024-12-08 20:53:34'),
(49, 'Story About You and Me', 'Hae-Won Jeon', 'Memories Through the Eyes of a Child Who Has Lost a Sibling or Friend.', 'Romantic', '11.99', 'imges/Romantic_Section/4.png', '2024-12-08 20:55:01'),
(50, 'Desure', 'Harumi Kobayashi', 'From the windswept, craggy coast of a remote British Isle comes the thrilling tale of a daring lady and a dangerous knight bound by the tempests of fate.', 'Romantic', '11.00', 'imges/Romantic_Section/5.png', '2024-12-08 20:56:08'),
(51, 'Esabella', 'Olivia Wilson', 'Isabella accompanies her husband to the hard mining world of the Northern Cape. After the birth of her daughter, life knocks her off her feet, and she must confront the unimaginable. She finds reconciliation in unexpected places: her therapist is the southeaster on Bloubergstrand.', 'Romantic', '19.99', 'imges/Romantic_Section/6.png', '2024-12-08 20:57:25'),
(52, 'Waiting For You', 'Olivia Wilson', 'Waiting for You is pretty much the story of Marisa deciding which boy to choose. There is very little chemistry between her and her love interest.', 'Romantic', '13.00', 'imges/Romantic_Section/7.png', '2024-12-08 20:58:43'),
(53, 'My Summer in Italy', 'Claudia Wilson', 'This emotional and magical tale explores the complexities of mother-daughter relationships and delves into the profound impact of loss.', 'Romantic', '21.99', 'imges/Romantic_Section/8.png', '2024-12-08 21:00:01'),
(54, 'We Above All', 'Raymond Redington', 'The story commences by imagining the thoughts of Jesus while he is on the cross at Calvary.', 'Romantic', '21.00', 'imges/Romantic_Section/9.png', '2024-12-08 21:02:21'),
(55, 'Palace of Silver', 'Hannah West', 'Two queens confront the ultimate choice as a rebellion emerges against a dangerous despot - and both sides want them dead. When the world of magic is under threat, is loyalty worth their lives? Wickedness awaits in this exhilarating installment in the acclaimed Nissera Chronicles.', 'Romantic', '24.99', 'imges/Romantic_Section/10.png', '2024-12-08 21:04:15'),
(56, 'Daughter of The Moon Goddess', 'Sue Lynn Tan', 'Daughter of the Moon Goddess begins an enchanting, romantic duology which weaves ancient Chinese mythology into a sweeping adventure of immortals and magic, of loss and sacrifice--where love vies with honor, dreams are fraught with betrayal, and hope emerges triumphant.', 'Romantic', '11.00', 'imges/Romantic_Section/11.png', '2024-12-08 21:05:20'),
(57, 'A Broken Heart', 'Mohammed Salah', 'It\'s a spellbinding adventure filled with romance, mystery, and just the right amount of danger. The story follows Evangeline Fox.', 'Romantic', '31.99', 'imges/Romantic_Section/12.png', '2024-12-08 21:06:34'),
(58, 'Forbidden to Love', 'Hind Alqahtani', 'Forbidden to Love is a captivating romance novel that delves into the forbidden love between two individuals from rival families. It explores the challenges they face and the sacrifices they make in order to be together.', 'Romantic', '4.99', 'imges/Romantic_Section/13.png', '2024-12-08 21:08:06'),
(59, 'Stay With Me', 'Claudia Wilson', 'Stay With Me is about a married Nigerian couple, Yejide and Akin, who experience ups and downs while trying to conceive and raise children. The couple previously agreed to pass on some of their culture\'s traditions in favor of having a more modern marriage.', 'Romantic', '22.50', 'imges/Romantic_Section/14.png', '2024-12-08 21:09:04'),
(60, 'Love', 'Olivia Wilson', 'My favorite thing about her is her deep love for her community and how she shares her love through the gift of food.', 'Romantic', '33.00', 'imges/Romantic_Section/15.png', '2024-12-08 21:11:23'),
(61, 'My First Love', 'Olivia Wilson', 'Amy Wyse has everything—except love. She doesn\'t want a boyfriend to get in the way of her dreams of college and a swimming scholarship, goals toward which she\'s worked hard. But then she\'s swept off her feet by Chris Shepherd, an irresistible senior from the swim team. Suddenly Amy has romance and a promising future.', 'Romantic', '49.99', 'imges/Romantic_Section/16.png', '2024-12-08 21:12:23');
